<template><section class="personal-recs" :class="{full}"><header><div><div class="personal-title-row"><h2 class="panel-title" role="button" :tabindex="full?-1:0" data-home-panel="personal" @keydown="titleKey" @click="setCohort('personal')"><Sparkles :size="16" :stroke-width="1.6"/>可能想唱</h2><div v-if="!full" class="cohort-tabs"><button v-for="c in cohorts" :key="c.id" :class="{on:cohort===c.id}" @click="setCohort(c.id)">{{c.label}}</button></div></div><small>{{cohort==='personal'?(data.learning?'越唱越懂你的口味':'先从曲库发现，唱过后会更懂你'):cohorts.find(c=>c.id===cohort)?.label+'回忆精选 · 500首'}}</small></div><button v-if="cohort==='personal'" @click="load(true)" :aria-busy="busy" :aria-disabled="busy"><RefreshCw :size="13"/>换一批</button><button v-else @click="setCohort('personal')">智能</button><button v-if="!full" @click="router.push('/recommendations')">更多 ›</button></header><div v-if="error" class="status">{{error}} <button @click="load()">重试</button></div><PagedCarousel v-else :items="cohort==='personal'?data.items||[]:null" :loader="cohort==='personal'?null:loadCohort" :page-size="6" :columns="2" :controls="full" :query-key="cohort"><template #default="{items}"><article v-for="item in items" :key="cohort==='personal'?item.song.id:cohort+':'+item.rank" class="personal-song"><button class="personal-pick" @click="order(item)"><b>{{item.song?.title||item.title}}</b><span>{{(item.song?.artist||item.artists?.join(' / ')||'未识别歌手')+(item.song?.source==='bilibili'?' · '+formatVideoViews(item.song.views):'')}}</span><small>{{item.warning||item.reason}}</small><em>{{isOrdered(item)?'已点':item.available===false?'B站找歌':player.isPlaying?'＋ 点歌':'立即唱'}}</em></button><button v-if="full&&cohort==='personal'" class="hide-pick" @click="dismiss(item)" :aria-label="'暂不推荐'+item.song.title">暂不推荐</button></article></template></PagedCarousel><footer><span>{{data.warning||(data.backupDirty?'偏好有更新 · 备份后可在其他设备恢复':data.backupStatus||'偏好保存在本机 · 与曲库一起备份到115')}}</span><button @click="backup">备份</button></footer></section></template>
<script setup>
import {formatVideoViews} from '../utils/videoViews'
import {ref,onMounted,onUnmounted} from 'vue'
import {Sparkles,RefreshCw} from 'lucide-vue-next'
import {useRouter} from 'vue-router'
import {usePlayerStore} from '../stores/player'
import {useToast} from '../composables/useToast'
import PagedCarousel from './PagedCarousel.vue'
import api from '../api/client'
const props=defineProps({full:Boolean})
const cohort=ref('personal'),cohorts=[{id:'era70',label:'70后'},{id:'era80',label:'80后'},{id:'era90',label:'90后'},{id:'era00',label:'00后'}]
const data=ref({items:[]}),busy=ref(false),error=ref(''),router=useRouter(),player=usePlayerStore(),{toast}=useToast()
function titleKey(event){if(props.full)return;if(event.key==='ArrowLeft'){event.preventDefault();event.stopPropagation();document.querySelector('[data-home-panel="chart"]')?.focus()}else if(event.key==='ArrowDown'){event.preventDefault();event.stopPropagation();event.target.closest('section')?.querySelector('.swiper-slide-active .personal-pick')?.focus()}}
function isOrdered(item){return !!item.song&&player.orderedSongIds.has(String(item.song.id))}
function setCohort(id){cohort.value=id;error.value='';if(id==='personal')load()}
async function loadCohort(page){return (await api.collection(cohort.value,page*6,7)).items}
async function load(refresh=false){if(busy.value||cohort.value!=='personal')return;busy.value=true;try{const next=await api.recommendations(refresh===true);if(JSON.stringify(next.items)!==JSON.stringify(data.value.items))data.value=next;else data.value={...next,items:data.value.items};error.value=''}catch(e){error.value=e.message}finally{busy.value=false}}
async function order(item){if(item.available===false||!item.song){if(item.warning)toast(item.warning);router.push({name:'bilibili',query:{keyword:[item.title,...(item.artists||[]),'MV'].join(' '),matchTitle:item.title,matchArtists:JSON.stringify(item.artists||[])}});return}if(isOrdered(item)){toast('这首歌已点');return}try{player.applySnapshot(await api.control('order',{song_id:item.song.id,origin:item.origin}));toast('已点歌');await load()}catch(e){toast(e.message)}}
async function dismiss(item){try{data.value=await api.dismissRecommendation(item.song.id)}catch(e){toast(e.message)}}
async function backup(){try{const result=await api.backupRecommendations();toast(result.status);load()}catch(e){toast(e.message)}}
let timer
onMounted(()=>{load();timer=setInterval(()=>{if(!document.hidden&&(!window.Woniu?.songbookVisible||window.Woniu.songbookVisible()))load()},15000);window.addEventListener('woniu-change',load)})
onUnmounted(()=>{clearInterval(timer);window.removeEventListener('woniu-change',load)})
</script>
<style scoped>
.personal-recs{display:flex;flex-direction:column;min-height:0;height:100%;border:1px solid var(--accent-line);border-radius:16px;background:var(--panel);padding:12px 14px;gap:8px;box-shadow:var(--shadow)}.personal-recs.full{border:0;background:none;padding:0;box-shadow:none}header{display:flex;align-items:center;gap:7px;flex:none;min-height:30px}header>div{min-width:0;flex:1}h2{font-size:14px;margin:0;display:flex;align-items:center;gap:7px;font-weight:600}h2 svg{color:var(--gold)}header small{display:block;font-size:9px;color:var(--dim2);margin-top:4px}header button{display:flex;align-items:center;gap:5px}button{background:var(--panel2);color:var(--dim);border:1px solid var(--glass-border);border-radius:7px;padding:6px 8px;font-size:10px;flex:none}header button[aria-busy=true] svg{opacity:.5}.paged-carousel{flex:1;min-height:0}.personal-song{position:relative;display:flex;flex-direction:column;min-height:0;margin:4px 0;border-radius:11px;background:var(--tile);border:1px solid var(--glass-border);box-shadow:inset 0 1px 0 var(--highlight);overflow:hidden}.personal-pick{flex:1;min-height:0;text-align:left;position:relative;background:none;padding:6px 11px;border:0;color:var(--text);display:flex;flex-direction:column;justify-content:center;gap:3px;width:100%}.personal-pick b{flex-shrink:0;font-size:13px;font-weight:600;line-height:1.2;overflow:hidden;text-overflow:ellipsis;white-space:nowrap;max-width:100%;padding-right:24px}.personal-pick span{flex-shrink:0;font-size:10px;color:var(--dim);line-height:1.2;max-width:100%;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}.personal-pick small{flex-shrink:0;font-size:9px;color:var(--gold);line-height:1.2;white-space:nowrap;overflow:hidden;text-overflow:ellipsis;max-width:100%;opacity:.85}.personal-pick em{position:absolute;right:9px;top:11px;font-size:8px;font-style:normal;color:var(--gold);max-width:28px;line-height:1.3;text-align:right}.hide-pick{position:absolute;right:4px;bottom:4px;min-height:18px;font-size:9px;padding:3px 6px}.full .personal-pick small{padding-right:58px}.full h2{font-size:19px}.full header{margin-bottom:4px}.full .personal-pick b{font-size:15px}.full .personal-pick span{font-size:11px}.full .personal-pick{gap:3px;padding:6px 12px}footer{display:flex;align-items:center;gap:6px;color:var(--dim2);font-size:8px;flex:none}footer span{flex:1;overflow:hidden;text-overflow:ellipsis;white-space:nowrap}footer button{font-size:9px;padding:4px 7px;background:transparent}.status{flex:1;display:grid;place-content:center;color:var(--dim);font-size:13px;gap:10px}
</style>

<style scoped>.panel-title:focus{outline:2px solid var(--gold);outline-offset:4px;border-radius:5px}</style>

<style scoped>.personal-title-row{display:flex;align-items:center;gap:10px;flex-wrap:wrap}.personal-title-row h2{flex:none}.cohort-tabs{display:flex;gap:8px}.cohort-tabs button{font-size:11px;padding:5px 6px;min-width:44px;min-height:30px;border-color:var(--line);white-space:nowrap}.cohort-tabs .on{color:var(--gold);background:var(--selected);border-color:var(--accent-line)}header small{overflow:hidden;text-overflow:ellipsis;white-space:nowrap}</style>
